create extension if not exists pgcrypto;
create type public.user_role as enum ('customer','admin'); create type public.order_status as enum ('pending','paid','failed','expired','refunded');
create table public.profiles(id uuid primary key references auth.users on delete cascade,full_name text,phone text,role user_role not null default 'customer',created_at timestamptz default now(),updated_at timestamptz default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.products(id text primary key,category_id uuid references public.categories,name text not null,slug text not null unique,description text not null,price bigint not null check(price>=0),sale_price bigint not null check(sale_price>=0 and sale_price<=price),status text not null default 'active' check(status in ('draft','active','archived')),metadata jsonb default '{}',created_at timestamptz default now(),updated_at timestamptz default now());
create table public.product_files(id uuid primary key default gen_random_uuid(),product_id text not null references public.products on delete cascade,storage_path text not null unique,file_name text not null,download_limit int default 5,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.coupons(id uuid primary key default gen_random_uuid(),code text not null unique,kind text check(kind in ('fixed','percent')),value int not null,active boolean default true,starts_at timestamptz,expires_at timestamptz,max_uses int,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.orders(id uuid primary key default gen_random_uuid(),order_number text not null unique,user_id uuid references auth.users,email text not null,customer_name text not null,phone text,subtotal bigint default 0,discount bigint default 0,total bigint not null,status order_status not null default 'pending',coupon_id uuid references public.coupons,paid_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders on delete cascade,product_id text not null references public.products,product_name text not null,unit_price bigint not null,quantity int not null default 1,license text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.payments(id uuid primary key default gen_random_uuid(),order_number text not null,provider text not null,provider_transaction_id text not null unique,status order_status not null,amount bigint not null,payload jsonb default '{}',created_at timestamptz default now(),updated_at timestamptz default now());
create table public.downloads(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users,product_file_id uuid not null references public.product_files,ip_hash text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.reviews(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users,product_id text references public.products,order_item_id uuid unique references public.order_items,rating int check(rating between 1 and 5),body text,status text default 'pending',created_at timestamptz default now(),updated_at timestamptz default now());
create table public.newsletter_subscribers(id uuid primary key default gen_random_uuid(),email text not null unique,confirmed_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create index products_category_idx on products(category_id); create index orders_user_idx on orders(user_id); create index orders_email_idx on orders(email); create index orders_status_idx on orders(status); create index order_items_order_idx on order_items(order_id); create index downloads_user_idx on downloads(user_id);
alter table profiles enable row level security; alter table categories enable row level security; alter table products enable row level security; alter table product_files enable row level security; alter table orders enable row level security; alter table order_items enable row level security; alter table payments enable row level security; alter table downloads enable row level security; alter table coupons enable row level security; alter table reviews enable row level security; alter table newsletter_subscribers enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role='admin')$$;
create policy "public active products" on products for select using(status='active' or is_admin()); create policy "public categories" on categories for select using(true); create policy "owner profile" on profiles for select using(id=auth.uid() or is_admin()); create policy "owner updates profile" on profiles for update using(id=auth.uid());
create policy "owner orders" on orders for select using(user_id=auth.uid() or is_admin()); create policy "owner items" on order_items for select using(exists(select 1 from orders where orders.id=order_id and (orders.user_id=auth.uid() or is_admin()))); create policy "owner downloads" on downloads for select using(user_id=auth.uid() or is_admin()); create policy "published reviews" on reviews for select using(status='published' or is_admin());
create policy "admin products" on products for all using(is_admin()) with check(is_admin()); create policy "admin files" on product_files for all using(is_admin()) with check(is_admin()); create policy "admin categories" on categories for all using(is_admin()) with check(is_admin()); create policy "admin coupons" on coupons for all using(is_admin()) with check(is_admin()); create policy "admin payments" on payments for select using(is_admin());
insert into storage.buckets(id,name,public) values('products','products',false) on conflict(id) do update set public=false; create policy "admin storage" on storage.objects for all using(bucket_id='products' and public.is_admin()) with check(bucket_id='products' and public.is_admin());
